query Query($where: PurchaseOrderLineWhereInput, $orderBy: [PurchaseOrderLineOrderByInput!], $first: Int, $after: String) {
  purchaseOrderLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        purchaseOrder {
          id
          number
        }
      }
    }
  }
}

